-- GRUPO AQUINO | SETUP FINAL (único arquivo SQL). Pode ser executado quantas vezes quiser; não apaga dados.
-- Execute no Supabase > SQL Editor ANTES de usar o sistema e ANTES de importar o CSV.
create extension if not exists pgcrypto;

do $$
declare t text; d text; c record;
begin
  -- 1) Tabelas (criadas só se não existirem)
  foreach t in array array['funcionarios','frota','equipamentos','lancamentos_ferias','lancamentos_medicos','lancamentos_faltas','lancamentos_disciplinares','lancamentos_materiais'] loop
    execute format('create table if not exists public.%I (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now())', t);
    execute format('alter table public.%I add column if not exists updated_at timestamptz', t);
  end loop;

  -- 2) Colunas usadas pelo sistema
  for t, d in select * from (values
   ('funcionarios','matricula text,matricula_origem text,nome text,funcao text,codigo_funcao text,equipe text,data_cadastro date default current_date,data_admissao date,data_demissao date,situacao text default ''ATIVO'',ativo_origem text,observacao_status text,aviso_previo text,dias_aviso integer,observacao_importacao text,vt text,tipo_contratacao text,substituido_nome text,substituicao_origem text,substituicao_data date,substituicao_motivo text,substituicao_tempo text,cpf text,cpf_emissao date,rg text,rg_emissao date,pis text,pis_emissao date,titulo_eleitor text,titulo_zona text,titulo_secao text,titulo_emissao date,ctps_digital text,ctps text,ctps_serie text,ctps_emissao date,cnh text,cnh_categoria text,cnh_emissao date,cnh_validade date,cnh_tempo_validade text,nacionalidade text,naturalidade text,naturalidade_uf text,data_nascimento date,idade text,cep text,endereco text,numero text,complemento text,bairro text,cidade text,uf text,celular text,telefone text,email text,sexo text,raca text,grau_instrucao text,nome_mae text,nome_pai text,estado_civil text,uniforme text,camisa text,calca text,botina text,banco text,agencia text,conta text,afastamento_data date,afastamento_motivo text,afastamento_dias integer,afastamento_retorno date,observacao text'),
   ('frota','placa text,modelo text,marca text,ano integer,tipo text,situacao text default ''ATIVO'',quilometragem numeric,validade_documento date,observacao text'),
   ('equipamentos','codigo text,nome text,categoria text,marca_modelo text,situacao text default ''ATIVO'',data_aquisicao date,validade date,observacao text'),
   ('lancamentos_ferias','matricula text,funcionario text,funcao text,admissao date,tempo_servico text,periodo_aquisitivo text,quantidade_dias integer,inicio_gozo date,fim_gozo date,data_retorno date,observacao text'),
   ('lancamentos_medicos','numero_registro bigint generated by default as identity,data_entrega date,matricula text,funcionario text,funcao text,admissao date,tempo_servico text,sistema text,tipo text,data_ocorrido date,hora_inicial time,hora_final time,tempo_atendimento text,paciente text,profissional text,crm_cro text,especialidade text,cid10 text,cid_descricao text,afastamento text,apto text,dias_afastamento integer,data_retorno date,local_atendimento text,observacao text'),
   ('lancamentos_faltas','numero_registro bigint generated by default as identity,data_inclusao date,matricula text,funcionario text,funcao text,admissao date,tempo_servico text,data_ausencia date,motivo text,observacao text'),
   ('lancamentos_disciplinares','numero_registro bigint generated by default as identity,data_inclusao date,matricula text,funcionario text,funcao text,admissao date,tempo_servico text,data_ocorrido date,tipo text,motivo text,dias_afastamento integer,data_retorno date,aplicado_por text,testemunha1 text,testemunha2 text,observacao text'),
   ('lancamentos_materiais','numero_registro bigint generated by default as identity,data_inclusao date,matricula text,funcionario text,funcao text,admissao date,tempo_servico text,data_entrega date,tipo text,tamanho text,status_item text,quantidade numeric default 1,ca text,validade date,observacao text')
  ) v(a,b) loop
    foreach d in array string_to_array(d,',') loop
      execute format('alter table public.%I add column if not exists %s', t, d);
    end loop;
  end loop;

  -- 3) Matrícula passa a TEXTO em todas as tabelas (códigos longos) e remove checks antigos de 6 dígitos
  foreach t in array array['funcionarios','lancamentos_ferias','lancamentos_medicos','lancamentos_faltas','lancamentos_disciplinares','lancamentos_materiais'] loop
    execute format('alter table public.%I alter column matricula type text using matricula::text', t);
    for c in select conname from pg_constraint where conrelid=format('public.%I',t)::regclass and contype='c' and pg_get_constraintdef(oid) ilike '%matricula%' loop
      execute format('alter table public.%I drop constraint %I', t, c.conname);
    end loop;
  end loop;

  -- 4) Segurança: RLS ligado; somente usuários autenticados acessam
  foreach t in array array['funcionarios','frota','equipamentos','lancamentos_ferias','lancamentos_medicos','lancamentos_faltas','lancamentos_disciplinares','lancamentos_materiais'] loop
    execute format('alter table public.%I enable row level security', t);
    foreach d in array array['select','insert','update','delete'] loop
      execute format('drop policy if exists "authenticated %s" on public.%I', d, t);
    end loop;
    execute format('create policy "authenticated select" on public.%I for select to authenticated using (true)', t);
    execute format('create policy "authenticated insert" on public.%I for insert to authenticated with check (true)', t);
    execute format('create policy "authenticated update" on public.%I for update to authenticated using (true) with check (true)', t);
    execute format('create policy "authenticated delete" on public.%I for delete to authenticated using (true)', t);
  end loop;
end $$;

-- 5) Unicidade (evita matrícula/placa/código duplicados)
create unique index if not exists funcionarios_matricula_uk on public.funcionarios(matricula);
create unique index if not exists frota_placa_uk on public.frota(placa);
create unique index if not exists equipamentos_codigo_uk on public.equipamentos(codigo);

-- 5b) Ajustes de Atestados e Faltas (nova versão)
alter table public.lancamentos_medicos add column if not exists dia_completo boolean default false;
alter table public.lancamentos_medicos add column if not exists data_termino date;
alter table public.lancamentos_faltas add column if not exists sistema text;
update public.lancamentos_medicos set tipo='DECLARAÇÃO DE COMPARECIMENTO' where tipo='DECLARAÇÃO';
update public.lancamentos_medicos set especialidade='OUTROS' where especialidade='OUTRO';
update public.lancamentos_medicos set data_termino=data_ocorrido+(dias_afastamento-1) where data_termino is null and data_ocorrido is not null and coalesce(dias_afastamento,0)>0;

-- 5c) Férias, Advertências e Materiais (nova versão)
alter table public.lancamentos_ferias add column if not exists periodo_aquisitivo_inicio date;
alter table public.lancamentos_ferias add column if not exists periodo_aquisitivo_fim date;
alter table public.lancamentos_disciplinares add column if not exists data_aplicada date;
alter table public.lancamentos_materiais add column if not exists ficha_epi text;
alter table public.lancamentos_materiais add column if not exists tempo_validade integer;

-- 6) Atualiza o cache de esquema da API (corrige erro HTTP 400 por coluna desconhecida)
notify pgrst, 'reload schema';
